<?php

declare(strict_types=1);

namespace Tests\Generated\MyCrud\Country;

use CodeIgniter\Test\CIUnitTestCase;

/**
 * Structural smoke test generated by myCrudCI4.
 *
 * Verifies that the components required by the architecture are published and
 * loadable through the autoloader. It does not access application data.
 */
final class CountryStructureTest extends CIUnitTestCase
{
    private const EXPECTED_CLASSES = array (
  0 => 'App\\Models\\CountryModel',
  1 => 'App\\Controllers\\CountryController',
  2 => 'App\\Validation\\CountryRules',
  3 => 'App\\Entities\\CountryEntity',
  4 => 'App\\Services\\CountryService',
  5 => 'App\\Controllers\\Api\\V1\\CountryApiController',
  6 => 'App\\API\\Resources\\CountryResource',
  7 => 'App\\Validation\\CountryApiRules',
);

    public function testGeneratedClassesAreAutoloadable(): void
    {
        foreach (self::EXPECTED_CLASSES as $class) {
            $this->assertTrue(
                class_exists($class),
                'Generated class is not autoloadable: ' . $class
            );
        }
    }
}
